      "rules": [
        {
          "type": "position_near_with_facing",
          "params": {
            "target": [9, 1, 6],
            "max_distance": 8,
            "facing_tolerance": 60,
            "coordinate_frame": "spawn_relative"
          }
        }
      ]
    },
    {
      "task": "find purple_bed",
      "milestone_id": "find_purple_bed",
      "description": "Uses position_near_with_facing because this is a find/locate task. The purple bed is inside the cabin at spawn-relative (13,0,7) foot and (14,0,7) head. Target is set to (13, 1, 7) at eye-level. Max distance is 5 to require the player to be at or inside the cabin doorway (doorway is at x=11, bed is at x=13-14). Facing tolerance of 60 degrees ensures the player is looking at the bed.",
      "rules": [
        {
          "type": "position_near_with_facing",
          "params": {
            "target": [13, 1, 7],
            "max_distance": 5,
            "facing_tolerance": 60,
            "coordinate_frame": "spawn_relative"
          }
        }
      ]
    }
  ]
